DROP TABLE IF EXISTS `product_vendors`;
CREATE TABLE `product_vendors` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `purchase_date` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `expiry_date` timestamp NULL DEFAULT NULL,
  `go_down_product_id` bigint(20) unsigned NOT NULL,
  `vendor_id` bigint(20) unsigned NOT NULL,
  `gst` float(3,2) NOT NULL DEFAULT 0.00,
  `actual_price` float(10,2) NOT NULL,
  `buying_price` double NOT NULL,
  `stock_quantity` double NOT NULL,
  `unit_id` bigint(20) unsigned NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `is_deleted` enum('0','1') NOT NULL DEFAULT '0' COMMENT '0=>No,1=>Yes',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `product_vendors_go_down_product_id_foreign` (`go_down_product_id`),
  KEY `product_vendors_vendor_id_foreign` (`vendor_id`),
  KEY `product_vendors_unit_id_foreign` (`unit_id`),
  CONSTRAINT `product_vendors_go_down_product_id_foreign` FOREIGN KEY (`go_down_product_id`) REFERENCES `go_down_products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_vendors_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_vendors_vendor_id_foreign` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=351 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

